import React from 'react';
import { useLanguage } from '../context/LanguageContext';

const MyDecks = () => {
  const { t } = useLanguage();

  return (
    <div className="my-decks-page">
      <div className="page-header">
        <h1>
          <i className="fas fa-layer-group"></i>
          {t('navMyDecks', 'Meus Decks')}
        </h1>
        <p>{t('myDecksPageDesc', 'Gerencie seus decks de flashcards')}</p>
      </div>

      <div className="content-container">
        <div className="coming-soon">
          <i className="fas fa-tools"></i>
          <h2>{t('comingSoon', 'Em breve!')}</h2>
          <p>{t('myDecksComingSoon', 'Esta página está sendo migrada para React. Em breve você terá acesso a todos os seus decks.')}</p>
        </div>
      </div>
    </div>
  );
};

export default MyDecks;
